    print!("Clearing {description} ... ");
    match fs::remove_file(&path) {
        Err(err) if err.kind() == io::ErrorKind::NotFound => {
            println!("skipped (not present)");
        }
        Err(err) => {
            println!("could not remove the cache file {path:?}: {err}");
        }
        Ok(_) => println!("okay"),
    }
}
